<?php declare(strict_types=1);namespace NpmGateway\Tests\Unit;use NpmGateway\Http\Response;use NpmGateway\ValueObjects\AuthenticatedUser;use PHPUnit\Framework\TestCase;
final class MarketingFlyerGetPageRegressionTest extends TestCase{
 private string$views;
 protected function setUp():void{$this->views=dirname(__DIR__,2).'/resources/views';}
 public function testGetNewFlyerProducesHttp200WithRenderedFormWithoutPost():void{$properties=[['public_id'=>'01TESTPROPERTY0000000000000','display_name'=>'Pine Hill','property_code'=>'PH']];$months=['2026-08'=>'August 2026'];$month='2026-08';$property='';$type='standard';$user=new AuthenticatedUser(1,2,str_repeat('U',26),str_repeat('E',26),'kiyana','Kiyana');$csrfToken='csrf';$error='';ob_start();require$this->views.'/corporate/marketing/flyers/form.php';$response=new Response(200,(string)ob_get_clean());self::assertSame(200,$response->status);foreach(['New Flyer','id="flyer-upload"','name="property"','name="month"','name="type"','name="flyer"','Upload Flyer']as$text)self::assertStringContainsString($text,$response->body);self::assertGreaterThan(1000,strlen($response->body));}
 public function testGetFlyerLibraryStillProducesHttp200WithLibraryContent():void{$flyers=[];$properties=[];$months=['2026-08'=>'August 2026'];$month='2026-08';$property='';$user=new AuthenticatedUser(1,2,str_repeat('U',26),str_repeat('E',26),'kiyana','Kiyana');$csrfToken='csrf';$success='';$warning='';ob_start();require$this->views.'/corporate/marketing/flyers/index.php';$response=new Response(200,(string)ob_get_clean());self::assertSame(200,$response->status);self::assertStringContainsString('Marketing Flyers',$response->body);self::assertStringContainsString('No flyers found for August 2026.',$response->body);}
}
